const input = $input.first().json;

const errorMessage = (input.error_message || input.message || '').toLowerCase();
const statusCode = input.status_code || input.statusCode || 0;
const errorType = input.error_type || '';

let category = 'unknown';
let severity = 'warning';
let suggested_action = 'escalate';

// Classify by error type or message content
if (errorType === 'auth_error' || statusCode === 401 || statusCode === 403 || errorMessage.includes('unauthorized') || errorMessage.includes('forbidden') || errorMessage.includes('authentication')) {
  category = 'auth_error';
  severity = 'critical';
  suggested_action = 'escalate';
} else if (errorType === 'rate_limit' || statusCode === 429 || errorMessage.includes('rate limit') || errorMessage.includes('too many requests') || errorMessage.includes('quota')) {
  category = 'rate_limit';
  severity = 'warning';
  suggested_action = 'retry';
} else if (errorType === 'timeout' || errorMessage.includes('timeout') || errorMessage.includes('timed out') || errorMessage.includes('econnaborted')) {
  category = 'timeout';
  severity = 'warning';
  suggested_action = 'retry';
} else if (statusCode >= 400 && statusCode < 500) {
  if (statusCode === 400 || statusCode === 422 || errorMessage.includes('validation') || errorMessage.includes('invalid')) {
    category = 'validation_error';
    severity = 'info';
    suggested_action = 'ignore';
  } else {
    category = 'api_error';
    severity = 'warning';
    suggested_action = 'escalate';
  }
} else if (statusCode >= 500) {
  category = 'api_error';
  severity = 'critical';
  suggested_action = 'retry';
} else if (errorMessage.includes('validation') || errorMessage.includes('invalid')) {
  category = 'validation_error';
  severity = 'info';
  suggested_action = 'ignore';
} else if (errorMessage) {
  category = 'api_error';
  severity = 'warning';
  suggested_action = 'escalate';
}

return [{
  json: {
    error_id: input.error_id || $execution.id,
    category: category,
    severity: severity,
    suggested_action: suggested_action,
    original_error: {
      message: input.error_message || input.message || 'No error message provided',
      status_code: statusCode,
      error_type: errorType,
      source_workflow: input.source_workflow || 'unknown',
      source_node: input.source_node || 'unknown',
      api: input.api || 'unknown',
      client: input.client || 'unknown'
    },
    classified_at: new Date().toISOString()
  }
}];

const error = $input.first().json;

const logEntry = {
  log_type: 'error',
  error_id: error.error_id,
  category: error.category,
  severity: error.severity,
  suggested_action: error.suggested_action,
  source_workflow: error.original_error.source_workflow,
  source_node: error.original_error.source_node,
  api: error.original_error.api,
  client: error.original_error.client,
  error_message: error.original_error.message,
  status_code: error.original_error.status_code,
  classified_at: error.classified_at,
  logged_at: new Date().toISOString(),
  metadata: {
    workflow_id: $workflow.id,
    execution_id: $execution.id
  }
};

// In production, this would write to a data table or external logging service
// For now, we format and pass through the structured log entry
console.log(JSON.stringify(logEntry));

return [{ json: { ...error, log_entry: logEntry, logged: true } }];

